package com.aviatortrends.analyzer;
import android.app.*;import android.content.*;import android.media.projection.MediaProjectionManager;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {ResultStore store;LinearLayout root;TextView stats,history,status;int CAPTURE=41;int dp(float v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}TextView tv(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(z);t.setPadding(dp(14),dp(10),dp(14),dp(10));return t;}public void onCreate(Bundle b){super.onCreate(b);store=new ResultStore(this);build();}void build(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(14),dp(18),dp(14),dp(10));root.setBackgroundColor(Color.rgb(11,18,32));ScrollView sc=new ScrollView(this);sc.addView(root);setContentView(sc);root.addView(tv("AVIATOR TRENDS ANALYZER",24));root.addView(tv("OCR-only historical analysis • no betting automation",14));status=tv("● Monitoring stopped",14);root.addView(status);Button overlay=new Button(this);overlay.setText("Open floating overlay");overlay.setOnClickListener(v->openOverlay());root.addView(overlay);Button monitor=new Button(this);monitor.setText("Grant screen capture & start monitoring");monitor.setOnClickListener(v->requestCapture());root.addView(monitor);stats=tv("",15);root.addView(stats);root.addView(tv("Recent OCR history",18));history=tv("",14);root.addView(history);Button clear=new Button(this);clear.setText("Clear local history");clear.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Delete all results?").setMessage("This cannot be undone.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->{store.clear();refresh();}).show());root.addView(clear);root.addView(tv("Privacy: screenshots and OCR results stay on-device by default. Android may stop background capture due to battery or permission rules. Historical statistics are descriptive and do not predict future multipliers. Results are collected only from the authorized screen-capture monitoring flow; there is no manual-entry feature.",13));refresh();}void refresh(){List<Result> r=store.all();stats.setText(Stats.summary(r));StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(20,r.size());i++){Result x=r.get(i);b.append(String.format(Locale.US,"%.2fx  •  %s  •  %s\n",x.multiplier,x.source,new Date(x.timestamp)));}history.setText(b.length()==0?"No OCR results collected yet.":b.toString());}void openOverlay(){if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));return;}startService(new Intent(this,OverlayService.class));status.setText("● Overlay open");}void requestCapture(){MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);startActivityForResult(m.createScreenCaptureIntent(),CAPTURE);}protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==CAPTURE&&c==RESULT_OK){startForegroundService(new Intent(this,CaptureService.class));status.setText("● Capture permission granted; monitoring service active");Toast.makeText(this,"Capture consent granted. OCR processing stays on-device.",Toast.LENGTH_LONG).show();}}}
